j:jelly.g:evaluate:
 var part1 = jelly.jvar_cat_item.getName();
 if (part1 == null || part1 == '' || part1 == 'undefined')
	 part1 = '';
 var part2 = jelly.jvar_cat_item.getShortDescription();
 if (part2 == null || part2 == '' || part2 == 'undefined')
	 part2 = '';
 var partMid = ' - ';
 if (part1 == '' || part2 == '')
	 partMid = '';
 var jvar_questionHelpTag = part1 + partMid + part2;
 var escapedText = gs.getProperty('glide.ui.escape_text', true);
 if (escapedText == 'false')
	jvar_questionHelpTag = GlideStringUtil.escapeHTML(jvar_questionHelpTag);

 jvar_questionHelpTag;
